topics.examples:
#include <iostream>

class Counter {
private:
    int count;
public:
    Counter() : count(0) {}
    void increment() { count++; }
    int get() const { return count; }
};

int main() {
    Counter c;
    c.increment();
    std::cout << "Count: " << c.get() << std::endl;
    return 0;
}

